  Ltac chk1_absurd v K K2 :=
    exfalso; unfold sxb, b8 in K, K2; rewrite (Z_to_bv_signed 8 v) in K, K2;
    rewrite (bv_swrap_small 8 v) in K, K2 by (unfold bv_half_modulus, bv_modulus; cbn; lia);
    rewrite ?unsigned_lit in K by lia; rewrite ?unsigned_lit in K2 by lia; rewrite ?land_7 in K2;
